<template>
  <div class="mission-card-strip">
    <CompactMissionCard
      v-for="mission in missions"
      :key="mission.id"
      :mission="mission"
      :progress="getProgress(mission.id)"
      @click="$emit('click-mission', $event)"
    />
    <div v-if="missions.length === 0" class="mission-card-strip__empty text-grey-6">
      {{ $t('no_active_missions') || 'No active missions' }}
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetMission } from 'src/@types/docnet';
import CompactMissionCard from './CompactMissionCard.vue';

export default defineComponent({
  name: 'MissionCardStrip',

  components: {
    CompactMissionCard,
  },

  props: {
    missions: {
      type: Array as PropType<DocNetMission[]>,
      required: true,
    },
    getProgress: {
      type: Function as PropType<(id: string) => number>,
      required: true,
    },
  },

  emits: ['click-mission'],
});
</script>

