<template>
  <div class="mission-control">
    <!-- Top strip: compact mission cards -->
    <MissionCardStrip
      :missions="controlMissions"
      :get-progress="missionStore.getMissionProgress"
      @click-mission="goToMission"
    />

    <!-- Main area: chat + optional inbox sidebar -->
    <div class="mission-control__main">
      <OrchestratorChat
        class="mission-control__chat"
        @mission-created="onMissionCreated"
      />

      <ResizeHandle
        v-if="inboxOpen"
        @resize-start="isResizing = true"
        @resize-move="onResizeMove"
        @resize-end="isResizing = false"
      />

      <InboxSidebar
        v-model:open="inboxOpen"
        :width="inboxWidth"
        :focus-item-id="inboxFocusItemId"
      />
    </div>

  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetInboxStore } from 'src/store/DocNet/docnet-inbox.store';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import MissionCardStrip from './components/MissionCardStrip.vue';
import OrchestratorChat from './components/OrchestratorChat.vue';
import InboxSidebar from './components/InboxSidebar.vue';
import ResizeHandle from './components/ResizeHandle.vue';

export default defineComponent({
  name: 'MissionControlPage',

  components: {
    MissionCardStrip,
    OrchestratorChat,
    InboxSidebar,
    ResizeHandle,
  },

  setup() {
    const missionStore = useDocNetMissionStore();
    const inboxStore = useDocNetInboxStore();
    const issueStore = useDocNetIssueStore();

    return { missionStore, inboxStore, issueStore };
  },

  data(): { inboxOpen: boolean; inboxWidth: number; isResizing: boolean; inboxFocusItemId: string | null } {
    return {
      inboxOpen: true,
      inboxWidth: 400,
      isResizing: false,
      inboxFocusItemId: null,
    };
  },

  computed: {
    controlMissions() {
      return this.missionStore.missions.filter(
        (m) => m.status !== 'completed' && m.status !== 'cancelled',
      );
    },
  },

  mounted() {
    this.missionStore.fetchMissions().catch(() => {});
    this.issueStore.fetchIssues().catch(() => {});
    this.inboxStore.fetchItems().catch(() => {});
  },

  methods: {
    goToMission(id: string) {
      this.$router.push(`/doc-net/missions/${id}`);
    },

    onMissionCreated(payload: { missionId: string; status: string; inboxItemId?: string }) {
      if (payload.status === 'waiting_approval' && payload.inboxItemId) {
        this.inboxOpen = true;
        this.inboxFocusItemId = payload.inboxItemId;
        this.inboxStore.fetchItems().catch(() => {});
      }
    },

    onResizeMove(clientX: number) {
      const container = this.$el as HTMLElement;
      const rect = container.getBoundingClientRect();
      this.inboxWidth = Math.max(280, Math.min(600, rect.right - clientX));
    },
  },
});
</script>

<style lang="scss" scoped>
.mission-control {
  display: flex;
  flex-direction: column;
  height: 100%;
  position: relative;
  overflow: hidden;

  &__main {
    flex: 1;
    display: flex;
    min-height: 0;
    overflow: hidden;
  }

  &__chat {
    flex: 1;
    min-width: 0;
  }

}
</style>
