            <!-- Message input: always visible for actionable types -->
            <q-input
              v-if="selectedItem.type === 'approval' || selectedItem.type === 'review' || selectedItem.type === 'question' || selectedItem.type === 'escalation'"
              v-model="resolutionNote"
              dense
              outlined
              autogrow
              :placeholder="$t('resolution_note_optional')"
            />

            <template v-if="selectedItem.type === 'approval'">
              <div class="row q-gutter-sm">
                <f-btn appearance="positive" :label="$t('approve')" icon="check" size="sm" :loading="acting" class="col" @click="doAction('approve')" />
