<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { useDocNetInboxStore } from 'src/store/DocNet/docnet-inbox.store';
import { storeToRefs } from 'pinia';
import type { DocNetInboxItem } from 'src/@types/docnet';
import InboxDropdownItem from '../../shared/InboxDropdownItem.vue';
import StatusBadge from '../../shared/StatusBadge.vue';
import AssigneeChip from '../../shared/AssigneeChip.vue';

const TYPE_COLOR_MAP: Record<string, string> = {
  approval: 'orange-7',
  escalation: 'deep-orange-7',
  question: 'blue-7',
  review: 'purple-7',
  notification: 'grey-7',
};

const TYPE_ICON_MAP: Record<string, string> = {
  approval: 'thumb_up',
  escalation: 'warning',
  question: 'help',
  review: 'rate_review',
  notification: 'notifications',
};

export default defineComponent({
  name: 'InboxSidebar',

  components: {
    InboxDropdownItem,
    StatusBadge,
    AssigneeChip,
  },

  props: {
    open: {
      type: Boolean,
      default: false,
    },
    width: {
      type: Number,
      default: 360,
    },
    focusItemId: {
      type: String as PropType<string | null>,
      default: null,
    },
  },

  emits: ['update:open'],

  setup() {
    const inboxStore = useDocNetInboxStore();
    const { pendingCount, pendingItems, recentlyResolvedItems } = storeToRefs(inboxStore);

    return { inboxStore, pendingCount, pendingItems, recentlyResolvedItems };
  },

  data() {
    return {
      selectedItemId: null as string | null,
      resolutionNote: '',
      acting: false,
    };
  },

  watch: {
    focusItemId: {
      immediate: true,
      handler(id: string | null) {
        if (id) {
          this.$emit('update:open', true);
          this.selectedItemId = id;
        }
      },
    },
  },

  computed: {
    sidebarStyle(): Record<string, string> {
      if (!this.open) {
        return { width: '40px', minWidth: '40px', maxWidth: '40px' };
      }
      return {
        width: this.width + 'px',
        maxWidth: this.width + 'px',
      };
    },

    selectedItem(): DocNetInboxItem | null {
      if (!this.selectedItemId) return null;
      return this.inboxStore.items.find((i) => i.id === this.selectedItemId) || null;
    },

  },

  methods: {
    typeColor(type: string): string {
      return TYPE_COLOR_MAP[type] || 'grey-7';
    },

    typeIcon(type: string): string {
      return TYPE_ICON_MAP[type] || 'notifications';
    },

    formatTime(isoDate: string): string {
      const date = new Date(isoDate);
      const now = new Date();
      const diffMs = now.getTime() - date.getTime();
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return 'just now';
      if (diffMins < 60) return `${diffMins}m ago`;
      if (diffHours < 24) return `${diffHours}h ago`;
      if (diffDays < 7) return `${diffDays}d ago`;
      return date.toLocaleDateString();
    },

    async doAction(action: 'approve' | 'reject' | 'reassign' | 'comment') {
      if (!this.selectedItemId) return;
      this.acting = true;
      try {
        await this.inboxStore.actOnItem(
          this.selectedItemId,
          action,
          this.resolutionNote ? { resolution_notes: this.resolutionNote } : undefined,
        );
        this.resolutionNote = '';
        this.selectedItemId = null;
      } catch (error) {
        console.error('[MissionControl] Inbox act failed:', error);
      } finally {
        this.acting = false;
      }
    },

    async doDismiss() {
      if (!this.selectedItemId) return;
      this.acting = true;
      try {
        await this.inboxStore.dismissItem(this.selectedItemId);
        this.selectedItemId = null;
      } catch (error) {
        console.error('[MissionControl] Inbox dismiss failed:', error);
      } finally {
        this.acting = false;
      }
    },

    async onAct(event: { id: string; action: 'approve' | 'reject' | 'reassign' | 'comment'; payload?: Record<string, unknown> }) {
      try {
        await this.inboxStore.actOnItem(event.id, event.action, event.payload);
      } catch (error) {
        console.error('[MissionControl] Inbox act failed:', error);
      }
    },

    async onDismiss(id: string) {
      try {
        await this.inboxStore.dismissItem(id);
      } catch (error) {
        console.error('[MissionControl] Inbox dismiss failed:', error);
      }
    },
  },
});
</script>

