<template>
  <div
    class="compact-mission-card"
    :class="[]"
    @click="$emit('click', mission.id)"
  >
    <div class="compact-mission-card__header">
      <q-badge
        v-if="namePrefix"
        color="blue-grey-3"
        text-color="blue-grey-9"
        :label="namePrefix"
        class="compact-mission-card__prefix"
      />
      <span class="compact-mission-card__name" :title="mission.name">
        {{ nameDisplay }}
      </span>
      <StatusBadge :status="mission.status" size="sm" />
    </div>

    <MissionProgressBar :percent="progress" :status-breakdown="statusBreakdown" label="" size="sm" :hide-legend="true" />

    <div class="compact-mission-card__footer">
      <span class="compact-mission-card__task-count">
        {{ (mission.issues || []).length }} {{ $t('issues') }}
      </span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetMission } from 'src/@types/docnet';
import { formatMissionSource } from 'src/utils/docnet/formatting';
import StatusBadge from '../../shared/StatusBadge.vue';
import MissionProgressBar from '../../Missions/components/MissionProgressBar.vue';

export default defineComponent({
  name: 'CompactMissionCard',

  components: {
    StatusBadge,
    MissionProgressBar,
  },

  props: {
    mission: {
      type: Object as PropType<DocNetMission>,
      required: true,
    },
    progress: {
      type: Number,
      default: 0,
    },
  },

  emits: ['click'],

  computed: {
    /** Human-readable source label shown as a badge (e.g. "Email").
     *  Pass ``$t`` so the badge follows the active locale; falls
     *  back to the hardcoded English label when the
     *  ``source_<token>`` key isn't translated yet. */
    namePrefix(): string {
      return formatMissionSource(this.mission, (k: string) => this.$t(k));
    },

    /** Mission name as-is — the legacy ``[Prefix]`` was stripped from
     * all rows in the DOCB-9880 data migration, so ``mission.name``
     * is already the clean display name.
     */
    nameDisplay(): string {
      return this.mission.name ?? '';
    },

    statusBreakdown(): Array<{ status: string; count: number; hideLegend?: boolean }> {
      const issues = this.mission.issues || [];
      const counts: Record<string, number> = {};
      for (const issue of issues) {
        counts[issue.status] = (counts[issue.status] || 0) + 1;
      }
      const items: Array<{ status: string; count: number; hideLegend?: boolean }> =
        Object.entries(counts).map(([status, count]) => ({ status, count }));

      // Add mission itself (not in legend)
      const missionStatus = this.mission.status === 'completed' ? 'done'
        : this.mission.status === 'active' ? 'in_progress'
        : this.mission.status;
      items.push({ status: missionStatus, count: 1, hideLegend: true });

      return items;
    },
  },
});
</script>

