<template>
  <div class="orchestrator-chat column">
    <!-- Header -->
    <div class="orchestrator-chat__header row items-center q-px-md q-py-sm">
      <div class="status-dot q-mr-sm" />
      <template v-if="selectedAgent">
        <q-avatar size="20px" color="primary" text-color="white" font-size="10px" class="q-mr-xs">
          {{ selectedAgent.agent.name.charAt(0) }}
        </q-avatar>
        <span class="text-subtitle2 text-weight-bold">{{ selectedAgent.agent.name }}</span>
        <q-btn flat round dense size="xs" icon="close" class="q-ml-xs" @click="clearSelectedAgent" />
      </template>
      <span v-else class="text-subtitle2 text-weight-bold">Orchestrator</span>
    </div>

    <!-- Messages -->
    <div ref="scrollArea" class="orchestrator-chat__messages col q-pa-md">
      <div
        v-for="(msg, idx) in messages"
        :key="idx"
        class="orchestrator-chat__message q-mb-md"
        :class="msg.isUser ? 'orchestrator-chat__message--user' : 'orchestrator-chat__message--agent'"
      >
        <div v-if="msg.agentName && !msg.isUser" class="text-caption text-grey-6 q-mb-xs q-px-xs">
          {{ msg.agentName }}
        </div>
        <div
          class="orchestrator-chat__bubble q-pa-sm q-px-md"
          :class="[
            msg.isUser ? 'orchestrator-chat__bubble--user' : 'orchestrator-chat__bubble--agent',
            msg.statusMessage ? 'orchestrator-chat__bubble--status' : '',
          ]"
        >
          <q-spinner-dots v-if="msg.typing" size="1.5em" />
          <div v-else-if="msg.missionLink">
            Mission started:
            <router-link :to="`/doc-net/missions/${msg.missionLink.id}`" class="mission-link">
              {{ msg.missionLink.name }}
            </router-link>
          </div>
          <div v-else v-html="formatMessage(msg.text)" />
        </div>
        <div
          class="text-caption q-mt-xs q-px-xs text-grey-6"
          :class="msg.isUser ? 'text-right' : 'text-left'"
        >
          {{ msg.time }}
        </div>
      </div>
    </div>

    <!-- Mention autocomplete -->
    <div v-if="showMentionMenu && filteredAgents.length" class="mention-menu q-pa-xs">
      <q-list dense>
        <q-item
          v-for="profile in filteredAgents"
          :key="profile.agent.id"
          clickable
          dense
          @click="insertMention(profile)"
        >
          <q-item-section avatar>
            <q-avatar size="24px" color="primary" text-color="white" font-size="12px">
              {{ profile.agent.name.charAt(0) }}
            </q-avatar>
          </q-item-section>
          <q-item-section>{{ profile.agent.name }}</q-item-section>
          <q-item-section side>
            <q-badge :label="profile.role" />
          </q-item-section>
        </q-item>
      </q-list>
    </div>

    <!-- Input -->
    <div class="orchestrator-chat__input q-pa-sm">
      <q-input
        v-model="inputText"
        :placeholder="inputPlaceholder"
        dense
        outlined
        class="orchestrator-chat__input-field"
        @keyup.enter="sendMessage"
      >
        <template #append>
          <f-btn
            appearance="flat"
            size="sm"
            icon="send"
            dense
            :blocked="!inputText.trim() || isSending"
            @click="sendMessage"
          />
        </template>
      </q-input>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, nextTick } from 'vue';
import { LocalStorage } from 'quasar';
import { CONSTANTS } from 'src/constants';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { docNetApiService } from 'src/services';
import { renderMarkdown } from 'src/utils/markdown';
import { DocNetGatewayEventType } from 'src/types/websocket';
import type { MissionProgressEvent } from 'src/types/websocket';
import type { DocNetAgentProfile } from 'src/@types/docnet';

type ChatMessage = {
  text: string;
  isUser: boolean;
  time: string;
  typing?: boolean;
  agentName?: string;
  /** If set, this message is a live status indicator (not final) */
  statusMessage?: boolean;
  /** If set, renders as a clickable link to this mission */
  missionLink?: { id: string; name: string };
};

export default defineComponent({
  name: 'OrchestratorChat',

  emits: ['mission-created', 'approval-required'],

  setup() {
    const missionStore = useDocNetMissionStore();
    const agentStore = useDocNetAgentStore();
    const wsStore = useDocNetWebSocketStore();
    return { missionStore, agentStore, wsStore };
  },

  data() {
    return {
      inputText: '',
      messages: [] as ChatMessage[],
      isSending: false,
      showMentionMenu: false,
      mentionQuery: '',
      selectedAgentId: null as string | null,
      /** Active WS unsubscribe function for current mission */
      wsUnsubscribe: null as (() => void) | null,
    };
  },

  computed: {
    filteredAgents(): DocNetAgentProfile[] {
      const q = this.mentionQuery.toLowerCase();
      return this.agentStore.profiles.filter(
        (p) => p.agent.name.toLowerCase().includes(q),
      );
    },
    selectedAgent(): DocNetAgentProfile | null {
      if (!this.selectedAgentId) return null;
      return this.agentStore.profiles.find((p) => p.agent.id === this.selectedAgentId) ?? null;
    },
    inputPlaceholder(): string {
      if (this.selectedAgent) {
        return `Message @${this.selectedAgent.agent.name}...`;
      }
      return this.$t('ask_orchestrator') as string;
    },
  },

  watch: {
    inputText(val: string) {
      const atIdx = val.lastIndexOf('@');
      if (atIdx === -1) {
        this.showMentionMenu = false;
        return;
      }
      const afterAt = val.slice(atIdx + 1);
      if (afterAt.includes(' ')) {
        this.showMentionMenu = false;
        return;
      }
      this.mentionQuery = afterAt;
      this.showMentionMenu = true;
    },
  },

  mounted() {
    this.messages.push({
      text: 'Describe a mission you\'d like to create and I\'ll get it started.',
      isUser: false,
      time: this.currentTime(),
    });
  },

  beforeUnmount() {
    if (this.wsUnsubscribe) {
      this.wsUnsubscribe();
      this.wsUnsubscribe = null;
    }
  },

  methods: {
    renderMarkdown,

    currentTime(): string {
      return new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    },

    formatMessage(text: string): string {
      return renderMarkdown(text);
    },

    scrollToBottom() {
      nextTick(() => {
        const el = this.$refs.scrollArea as HTMLElement | undefined;
        if (el) el.scrollTop = el.scrollHeight;
      });
    },

    insertMention(profile: DocNetAgentProfile) {
      const atIdx = this.inputText.lastIndexOf('@');
      this.inputText = this.inputText.slice(0, atIdx) + `@${profile.agent.name} `;
      this.selectedAgentId = profile.agent.id;
      this.showMentionMenu = false;
    },

    clearSelectedAgent() {
      this.selectedAgentId = null;
    },

    /** Remove the last status message (typing/progress) if present */
    removeStatusMessage() {
      const lastIdx = this.messages.length - 1;
      if (lastIdx >= 0 && (this.messages[lastIdx].typing || this.messages[lastIdx].statusMessage)) {
        this.messages.splice(lastIdx, 1);
      }
    },

    /** Subscribe to WS events for a mission and update chat in real time */
    subscribeToMission(missionId: string) {
      // Clean up any previous subscription
      if (this.wsUnsubscribe) {
        this.wsUnsubscribe();
      }

      this.wsUnsubscribe = this.wsStore.onMissionEvent(
        missionId,
        (eventType: string, data: MissionProgressEvent) => {
          this.handleMissionEvent(eventType, data);
        },
      );
    },

    handleMissionEvent(eventType: string, data: MissionProgressEvent) {
      switch (eventType) {
        case DocNetGatewayEventType.AGENT_START:
          // Replace typing indicator with "working" status
          this.removeStatusMessage();
          this.messages.push({
            text: `**${data.agent_name || 'Orchestrator'}** is analyzing your request...`,
            isUser: false,
            time: this.currentTime(),
            statusMessage: true,
          });
          this.scrollToBottom();
          break;

        case DocNetGatewayEventType.DELEGATION_STARTED:
          // Show delegation progress
          this.removeStatusMessage();
          this.messages.push({
            text: `Delegating to **${data.child_agent}**...`,
            isUser: false,
            time: this.currentTime(),
            statusMessage: true,
          });
          this.scrollToBottom();
          break;

        case DocNetGatewayEventType.CHILD_COMPLETED:
          // Show child completion progress
          this.removeStatusMessage();
          this.messages.push({
            text: `**${data.child_agent}** finished. Waiting for remaining agents...`,
            isUser: false,
            time: this.currentTime(),
            statusMessage: true,
          });
          this.scrollToBottom();
          break;

        case DocNetGatewayEventType.AGENT_COMPLETE:
          // Final response — remove any status message and show result
          this.removeStatusMessage();
          this.isSending = false;

          if (data.error) {
            this.messages.push({
              text: `An error occurred: ${data.error}`,
              isUser: false,
              time: this.currentTime(),
            });
          } else if (data.response) {
            this.messages.push({
              text: data.response,
              isUser: false,
              time: this.currentTime(),
              agentName: data.agent_name,
            });
          }

          // Emit events for parent components
          if (data.status === 'waiting_approval' && data.inbox_item_id) {
            this.$emit('approval-required', {
              missionId: data.mission_id,
              inboxItemId: data.inbox_item_id,
            });
          }

          // Refresh missions list
          this.missionStore.fetchMissions().catch(() => {});

          // Unsubscribe — mission complete
          if (this.wsUnsubscribe) {
            this.wsUnsubscribe();
            this.wsUnsubscribe = null;
          }
          this.scrollToBottom();
          break;
      }
    },

    async sendMessage() {
      const text = this.inputText.trim();
      if (!text || this.isSending) return;

      // Strip @mention from prompt text
      const prompt = text.replace(/@[\w\s-]+?\s/g, '').trim() || text;
      const agentId = this.selectedAgentId;

      this.messages.push({
        text,
        isUser: true,
        time: this.currentTime(),
      });
      this.inputText = '';
      this.isSending = true;
      this.scrollToBottom();

      // Show typing indicator
      this.messages.push({ text: '', isUser: false, time: '', typing: true });
      this.scrollToBottom();

      try {
        const payload: { prompt: string; agent_id?: string; language?: string } = { prompt };
        if (agentId) payload.agent_id = agentId;
        // Send user's selected UI language so agent responds in the same language
        const selectedLang = LocalStorage.getItem(CONSTANTS.selected_language) as string | null;
        if (selectedLang) payload.language = selectedLang;

        const res = await docNetApiService.chat(payload);

        if (res.mission_id) {
          this.$emit('mission-created', {
            missionId: res.mission_id,
            status: res.status,
            inboxItemId: res.inbox_item_id,
          });

          // Fetch missions so we can look up the name
          await this.missionStore.fetchMissions();
          const mission = this.missionStore.missions.find((m) => m.id === res.mission_id);
          const missionName = mission?.name || prompt;

          // Remove typing indicator and show "Mission started" link
          this.removeStatusMessage();
          this.isSending = false;

          this.messages.push({
            text: '',
            isUser: false,
            time: this.currentTime(),
            missionLink: { id: res.mission_id, name: missionName },
          });
        }
      } catch {
        this.removeStatusMessage();
        this.isSending = false;

        this.messages.push({
          text: 'Sorry, I encountered an error. Please try again.',
          isUser: false,
          time: this.currentTime(),
        });
      } finally {
        this.scrollToBottom();
      }
    },
  },
});
</script>

